-- EPICENTRO GOURMET - DATOS DE PRUEBA
-- Ejecutar COMPLETO en MySQL Workbench.
-- DESTINO EXCLUSIVO: test
-- PREVIO: crear test, apuntar DB_URL a esa base, iniciar la app
-- con ddl-auto=update para crear tablas y DETENER la app antes de cargar.
-- Tablas vacias e InnoDB. Requiere permisos CREATE ROUTINE, EXECUTE y ALTER ROUTINE.
-- No elimina filas ni tablas. La carga se rechaza si hay datos previos.
-- Ante un error SQL en la carga: ROLLBACK y propagacion del error.
-- Detener ejecucion ante errores en Workbench. No ejecutar partes sueltas.
-- Primavera: festival 01/10-30/11; pedidos 01/10-05/11 inclusive.
-- Invierno: festival y pedidos 01/07-31/08 completos.
-- Costos: referencia del enunciado multiplicada por 4.5 y 4.3.
-- Se conservan precios de platos, usuarios y hashes BCrypt originales.
-- Contrasena de demostracion: 1234.
-- Totales: 2 costos, 2 festivales, 10 unidades, 51 usuarios, 51 roles,
-- 40 empleados, 10 cajeros, 30 cocineros, 50 platos, 4900 pedidos, 9800 items.

USE test;
SET NAMES utf8mb4;

DELIMITER $$
CREATE PROCEDURE cargar_datos_defensa_20261105()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF EXISTS (SELECT 1 FROM `costo` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `festival` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `user` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `user_role` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `unidad_venta` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `food_truck` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `puesto_desarmable` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `empleado` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `cajero` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `cocinero` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `plato` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `pedido` LIMIT 1)
        OR EXISTS (SELECT 1 FROM `item_pedido` LIMIT 1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Carga cancelada: se requieren tablas vacias. No se borraron datos.';
    END IF;

    START TRANSACTION;

    INSERT INTO `costo` (`id_costo`,`costo_superficies`,`costo_montaje`,`plus_electricidad`,`sueldo_base`,`plus_antiguedad`,`plus_cocinero`,`plus_ayudante`,`plus_lavaplatos`) VALUES
    (1,2250,45,9000,450000,22500,675000,450000,225000),
    (2,2150,43,8600,430000,21500,645000,430000,215000);

    INSERT INTO `festival` (`id_festival`,`nombre`,`temporada`,`fecha_inicio`,`fecha_fin`,`costo_id`,`activo`) VALUES
    (1,'Festival Gastronómico Primavera 2026','Primavera','2026-10-01','2026-11-30',1,1),
    (2,'Festival Gastronómico Invierno 2026','Invierno','2026-07-01','2026-08-31',2,0);

