    IF (SELECT COUNT(*) FROM pedido) <> 4900
       OR (SELECT COUNT(*) FROM item_pedido) <> 9800 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Conteos inesperados; carga revertida.';
    END IF;

    IF EXISTS (
        SELECT 1 FROM item_pedido i
        JOIN pedido p ON p.id_pedido = i.id_pedido
        JOIN plato pl ON pl.id_plato = i.id_plato
        WHERE p.id_unidad_venta <> pl.id_unidad_venta
           OR i.total_item <> i.cantidad * pl.precio_de_venta
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Inconsistencia en items; carga revertida.';
    END IF;

    IF EXISTS (SELECT 1 FROM pedido WHERE fecha > '2026-11-05') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pedidos posteriores al corte; carga revertida.';
    END IF;

    COMMIT;
END$$
DELIMITER ;

CALL cargar_datos_defensa_20261105();
DROP PROCEDURE cargar_datos_defensa_20261105;

SELECT 'CARGA FINALIZADA: 4900 pedidos y 9800 items' AS resultado;

-- CONTEOS: 2,10,51,51,40,10,30,50,4900,9800.
SELECT 'festivales' AS tabla, COUNT(*) AS cantidad FROM festival
UNION ALL SELECT 'unidades',COUNT(*) FROM unidad_venta
UNION ALL SELECT 'usuarios',COUNT(*) FROM `user`
UNION ALL SELECT 'roles',COUNT(*) FROM user_role
UNION ALL SELECT 'empleados',COUNT(*) FROM empleado
UNION ALL SELECT 'cajeros',COUNT(*) FROM cajero
UNION ALL SELECT 'cocineros',COUNT(*) FROM cocinero
UNION ALL SELECT 'platos',COUNT(*) FROM plato
UNION ALL SELECT 'pedidos',COUNT(*) FROM pedido
UNION ALL SELECT 'items',COUNT(*) FROM item_pedido;

-- Festival 1: duracion 61 dias, 36 dias con ventas y 1800 pedidos.
-- Festival 2: duracion 62 dias, 62 dias con ventas y 3100 pedidos.
SELECT f.id_festival,f.nombre,f.fecha_inicio,f.fecha_fin,
       DATEDIFF(f.fecha_fin,f.fecha_inicio)+1 AS dias,
       COUNT(p.id_pedido) AS pedidos
FROM festival f JOIN unidad_venta uv ON uv.id_festival=f.id_festival
LEFT JOIN pedido p ON p.id_unidad_venta=uv.id_unidad_venta
GROUP BY f.id_festival,f.nombre,f.fecha_inicio,f.fecha_fin
ORDER BY f.id_festival;

-- Unidades 1..5: 36 dias/360 pedidos; 6..10: 62 dias/620 pedidos.
SELECT id_unidad_venta,MIN(fecha) AS inicio,MAX(fecha) AS fin,
       COUNT(DISTINCT fecha) AS dias,COUNT(*) AS pedidos
FROM pedido GROUP BY id_unidad_venta ORDER BY id_unidad_venta;

-- Cero filas: cada unidad debe tener 10 pedidos por fecha.
SELECT id_unidad_venta,fecha,COUNT(*) AS pedidos
FROM pedido GROUP BY id_unidad_venta,fecha HAVING COUNT(*)<>10;

-- 4 empleados y 4 cuentas por unidad.
SELECT id_unidad_venta,COUNT(*) AS empleados,COUNT(id_user) AS cuentas
FROM empleado GROUP BY id_unidad_venta ORDER BY id_unidad_venta;

-- 3 categorias por unidad, cada una con un empleado.
SELECT e.id_unidad_venta,c.categoria,COUNT(*) AS empleados
FROM empleado e JOIN cocinero c ON c.id_empleado=e.id_empleado
GROUP BY e.id_unidad_venta,c.categoria ORDER BY e.id_unidad_venta,c.categoria;

-- Los siguientes conteos deben ser cero.
SELECT COUNT(*) AS items_unidad_incorrecta
FROM item_pedido i JOIN pedido p ON p.id_pedido=i.id_pedido
JOIN plato pl ON pl.id_plato=i.id_plato
WHERE p.id_unidad_venta<>pl.id_unidad_venta;

SELECT COUNT(*) AS importes_incorrectos
FROM item_pedido i JOIN plato pl ON pl.id_plato=i.id_plato
WHERE i.total_item<>i.cantidad*pl.precio_de_venta;

SELECT COUNT(*) AS empleados_sin_cuenta_o_estado_inconsistente
FROM empleado e LEFT JOIN `user` u ON u.id=e.id_user
WHERE u.id IS NULL OR e.activo<>u.enabled;

SELECT COUNT(*) AS pedidos_fuera_del_festival
FROM pedido p JOIN unidad_venta uv ON uv.id_unidad_venta=p.id_unidad_venta
JOIN festival f ON f.id_festival=uv.id_festival
WHERE p.fecha<f.fecha_inicio OR p.fecha>f.fecha_fin;

-- Los siguientes resultados tambien deben ser cero.
SELECT COUNT(*) AS codigos_invalidos
FROM unidad_venta WHERE codigo NOT REGEXP '^[A-Z0-9]{10}$';
SELECT COUNT(*) AS pedidos_posteriores_al_corte
FROM pedido WHERE fecha > '2026-11-05';

-- Costos actualizados por festival.
SELECT f.nombre,c.* FROM festival f JOIN costo c ON c.id_costo=f.costo_id;
